{
  "interpretation": {
    "name": "TightenF25AtSt1WithNR7",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Tighten all fasteners of the forklift variant F25 at station st1 with tool NR7, then evaluate and record the result, so the blocked unit can proceed.",
    "constraints": [
      "NR7 must be reserved exclusively before use and released afterwards",
      "The reservation lease is renewed with the reservation token by every tool-using Step, so each of these Steps depends on reserve-tool",
      "NR7 must be at st1 (transport-tool to 'station' completed) before configure-tool and tighten-fasteners",
      "transport-tool must be delegated to the Executor agvexecutor",
      "The tightening program is obtained only through get-program; no torque, tolerance or bolt count appears in the Recipe",
      "The tightening result must be evaluated against the program and recorded for traceability"
    ],
    "preference": "Return NR7 to the crib after use so the shared tool is available to other lines.",
    "priority": "high",
    "horizon": "immediate, single execution",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "tighten-f25-st1-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["fasten"],
            "dep": ["program", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "fasten",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure", "reserve"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "quality",
        "next": "return-and-release",
        "steps": [
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["fasten", "program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["fasten"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-and-release",
        "next": null,
        "steps": [
          {
            "name": "to-crib",
            "service": "transport-tool",
            "next": ["release"],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
